export{};for await(const line of console){const m=JSON.parse(line);if(m.id===undefined)continue;let result:any={};if(m.method==="initialize")result={userAgent:"fake",received:m.params};if(m.method==="account/read")result={account:{type:"chatgpt",planType:"pro"}};if(m.method==="account/login/start")result={type:m.params.type,deviceCode:"ephemeral-device-code"};if(m.method==="thread/start")result={thread:{id:"thread-1"}};if(m.method==="turn/start"){if(m.params.model==="tool-model")console.log(JSON.stringify({jsonrpc:"2.0",method:"item/commandExecution/request",params:{type:"shell"}}));else console.log(JSON.stringify({jsonrpc:"2.0",method:"item/agentMessage/delta",params:{delta:"answer"}}));result={usage:{inputTokens:2,outputTokens:1}}}if(m.method==="model/list")result={data:[{id:"codex-test"}]};if(m.method==="account/rateLimits/read")result={remaining:null};console.log(JSON.stringify({jsonrpc:"2.0",id:m.id,result}))}
